import ImagePreviewDialog from "./ImagePreviewDialog.vue";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogTicketDetails: Boolean,
    StoreObj: Object
  },
  mixins: [get_ticket_by_id, assign_ticket],
  components: {
    ImagePreviewDialog,
    SnackBar
  },
  data: () => ({
    agents: "",
    previewImage: "",
    loading: false,
    assigningAgent: false,
    DialogImagePreview: false,
    imagePreview: null,
    SnackBarComponent: {},
    ListAllTicketDetails: {},
    ListAllTicketDetailsAttachments: [],
    ListAllTicketDetailsComments: []
  }),
  computed: {
    reassignAgents() {
      const t = this.ListAllTicketDetails;
      if (Array.isArray(t.ticket_type_auto_assign_group) && t.ticket_type_auto_assign_group.length > 0) {
        return t.ticket_type_auto_assign_group.filter(email => email !== this.currentUserEmail).map(email => ({
          title: email,
          value: email
        }));
      }
      if (Array.isArray(t.category_auto_assign_group) && t.category_auto_assign_group.length > 0) {
        return t.category_auto_assign_group.filter(email => email !== this.currentUserEmail).map(email => ({
          title: email,
          value: email
        }));
      }
      const fallback = t.agents_list || [];
      return fallback.filter(email => email !== this.currentUserEmail).map(email => ({
        title: email,
        value: email
      }));
    },
    currentUserEmail() {
      return this.$store.getters.GetUserEmail || "";
    },
    hasValidAttachment() {
      const hasLocal = this.imagePreview && typeof this.imagePreview === "string";
      const hasBackend = Array.isArray(this.ListAllTicketDetailsAttachments) && this.ListAllTicketDetailsAttachments.length > 0 && typeof this.ListAllTicketDetailsAttachments[0] === "string" && this.ListAllTicketDetailsAttachments[0].trim().length > 0;
      return hasLocal || hasBackend;
    }
  },
  watch: {
    DialogTicketDetails(val) {
      if (val) {
        return this.GetTicketDetails();
      }
      this.resetLocalPreview();
    }
  },
  methods: {
    async GetTicketDetails() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(get_ticket_by_id, {
          input: {
            ticket_id: this.StoreObj.ticket_id
          }
        }));
        let resultObj = JSON.parse(result.data.get_ticket_by_id);
        if (resultObj.Status === "SUCCESS") {
          this.ListAllTicketDetails = resultObj.data.ticket || {};
          this.ListAllTicketDetailsComments = resultObj.data.comments || [];
          this.ListAllTicketDetailsComments.sort((a, b) => b.created_at - a.created_at);
          const rawAttachments = resultObj.data.ticket.attachments;
          if (Array.isArray(rawAttachments)) {
            this.ListAllTicketDetailsAttachments = rawAttachments.filter(u => u && typeof u === "string");
          } else if (rawAttachments && typeof rawAttachments === "string") {
            this.ListAllTicketDetailsAttachments = [rawAttachments];
          } else {
            this.ListAllTicketDetailsAttachments = [];
          }
          if (this.ListAllTicketDetailsAttachments.length > 0 && !this.imagePreview) {
            this.previewImage = this.ListAllTicketDetailsAttachments[0];
          } else {
            if (!this.imagePreview) this.previewImage = "";
          }
        } else {
          this.ListAllTicketDetails = {};
          this.ListAllTicketDetailsComments = [];
          this.ListAllTicketDetailsAttachments = [];
        }
      } catch (error) {
        this.ListAllTicketDetails = {};
        this.ListAllTicketDetailsComments = [];
        this.ListAllTicketDetailsAttachments = [];
      } finally {
        this.loading = false;
      }
    },
    async assignAgentMethod() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(assign_ticket, {
          input: {
            ticket_id: this.ListAllTicketDetails.ticket_id,
            assigned_to_email: this.agents
          }
        }));
        let resultObj = JSON.parse(result.data.assign_ticket);
        if (resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: "☑️ " + resultObj.Message
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "❎ " + (resultObj.Message || "Assign failed")
          };
        }
        this.DialogTicketDetailsEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "❎ Failed to assign ticket."
        };
      } finally {
        this.loading = false;
      }
    },
    ConvertCreatedAtDate(created_at) {
      if (!created_at) return "N/A";
      const timestamp = Number(created_at);
      if (isNaN(timestamp)) return "Invalid Date";
      const date = new Date(timestamp * 1000);
      if (isNaN(date.getTime())) return "Invalid Date";
      const yyyy = date.getFullYear();
      const mm = String(date.getMonth() + 1).padStart(2, "0");
      const dd = String(date.getDate()).padStart(2, "0");
      let hours = date.getHours();
      const minute = String(date.getMinutes()).padStart(2, "0");
      const ampm = hours >= 12 ? "PM" : "AM";
      hours = hours % 12;
      hours = hours ? hours : 12;
      const time = `${hours}:${minute} ${ampm}`;
      return `${dd}-${mm}-${yyyy}, ${time}`;
    },
    ConvertAssignedDate(assigned_at) {
